<script setup lang="ts">
import { computed, ref } from 'vue'
import { api, type ApiError } from './api'

type Page = 'workbench' | 'designer' | 'expense'
type NodeType = 'START' | 'USER_TASK' | 'CONDITION' | 'SERVICE_TASK' | 'END'
interface FlowNode { id: string; name: string; type: NodeType; x: number; y: number; assignee: string }
interface FlowEdge { id: string; source: string; target: string; condition: string; defaultBranch?: boolean }
interface Task { id: string; title: string; applicant: string; amount: string; risk: string; updated: string; status: string; version?: number }

const page = ref<Page>('workbench')
const loggedIn = ref(false)
const username = ref('')
const password = ref('')
const tenantId = ref('demo')
const notice = ref('')
const definitionId = ref('')
const definitionRevision = ref(0)
const serverAvailable = ref(false)
const activeTask = ref<Task | null>(null)
const taskTab = ref<'detail' | 'timeline' | 'audit'>('detail')
const taskFilter = ref('全部')
const tasks = ref<Task[]>([])

const nodes = ref<FlowNode[]>([
  { id: 'start', name: '开始', type: 'START', x: 44, y: 180, assignee: '' },
  { id: 'submit', name: '员工提交', type: 'USER_TASK', x: 210, y: 180, assignee: '申请人' },
  { id: 'manager', name: '部门负责人', type: 'USER_TASK', x: 400, y: 180, assignee: '部门负责人' },
  { id: 'amount', name: '金额判断', type: 'CONDITION', x: 590, y: 180, assignee: '' },
  { id: 'finance', name: '财务复核', type: 'USER_TASK', x: 780, y: 90, assignee: '财务负责人' },
  { id: 'end', name: '结束', type: 'END', x: 980, y: 180, assignee: '' }
])
const edges = ref<FlowEdge[]>([
  { id: 'e1', source: 'start', target: 'submit', condition: '' }, { id: 'e2', source: 'submit', target: 'manager', condition: '' },
  { id: 'e3', source: 'manager', target: 'amount', condition: '' }, { id: 'e4', source: 'amount', target: 'end', condition: 'amount <= 5000', defaultBranch: false },
  { id: 'e5', source: 'amount', target: 'finance', condition: 'amount > 5000' }, { id: 'e6', source: 'finance', target: 'end', condition: '' }
])
const selectedId = ref('amount')
const selectedEdgeId = ref('')
const dragging = ref<string | null>(null)
const history = ref<string[]>([])
const future = ref<string[]>([])
const palette = [{ type: 'USER_TASK' as NodeType, label: '人工审批', icon: '人' }, { type: 'CONDITION' as NodeType, label: '条件分支', icon: '◇' }, { type: 'END' as NodeType, label: '结束节点', icon: '●' }]
const selectedNode = computed(() => nodes.value.find(n => n.id === selectedId.value) ?? null)
const selectedEdge = computed(() => edges.value.find(e => e.id === selectedEdgeId.value) ?? null)
const visibleTasks = computed(() => taskFilter.value === '全部' ? tasks.value : tasks.value.filter(t => t.risk === taskFilter.value))
const ASSIGNEE_ROLE_MAP: Record<string, string> = {
  '申请人': 'EMPLOYEE',
  '申请人直属上级': 'MANAGER',
  '部门负责人': 'MANAGER',
  '财务负责人': 'FINANCE'
}

async function login() { if (!username.value || !password.value) { notice.value = '请输入用户名和密码'; return }; try { const result = await api.login({ tenantId: tenantId.value, username: username.value, password: password.value }); localStorage.setItem('agentflow.token', result.token); loggedIn.value = true; serverAvailable.value = true; notice.value = `已进入 ${tenantId.value} 工作空间`; await loadTasks() } catch (error) { serverAvailable.value = false; notice.value = (error as ApiError).message ?? '登录失败，请检查服务状态' } }
async function loadTasks() { try { const result = await api.tasks(); serverAvailable.value = true; tasks.value = result.map(item => ({ id: item.taskId, title: item.taskName, applicant: item.assignee ?? '待认领', amount: '—', risk: '普通', updated: item.createdAt ? new Date(item.createdAt).toLocaleString() : '刚刚', status: '待我审批', version: item.version })) ; if (!result.length) notice.value = '当前没有可处理的待办任务' } catch { serverAvailable.value = false; tasks.value = []; notice.value = '任务中心暂时无法连接服务端，请稍后重试' } }
function logout() { localStorage.removeItem('agentflow.token'); loggedIn.value = false; serverAvailable.value = false; username.value = ''; password.value = '' }
function selectTask(task: Task) { activeTask.value = task; taskTab.value = 'detail' }
async function action(name: string) { if (!activeTask.value) return; const actionName = name === '批准' ? 'APPROVE' : name === '退回' ? 'RETURN' : 'TRANSFER'; if (actionName === 'RETURN') { notice.value = '请填写退回原因后再提交'; return }; try { const result = await api.taskAction(activeTask.value.id, { action: actionName, expectedVersion: activeTask.value.version }); activeTask.value.status = result.applicationStatus; notice.value = `${name}已提交`; await loadTasks() } catch (error) { notice.value = (error as ApiError).message ?? `${name}失败，请刷新后重试` } }
function snapshot() { return JSON.stringify({ nodes: nodes.value, edges: edges.value }) }
function remember() { history.value.push(snapshot()); if (history.value.length > 50) history.value.shift(); future.value = [] }
function restore(raw: string) { const data = JSON.parse(raw) as { nodes: FlowNode[]; edges: FlowEdge[] }; nodes.value = data.nodes; edges.value = data.edges }
function undo() { const prev = history.value.pop(); if (!prev) return; future.value.push(snapshot()); restore(prev) }
function redo() { const next = future.value.pop(); if (!next) return; history.value.push(snapshot()); restore(next) }
function selectNode(node: FlowNode) { selectedId.value = node.id; selectedEdgeId.value = '' }
function selectEdge(edge: FlowEdge) { selectedEdgeId.value = edge.id; selectedId.value = '' }
function moveNode(event: MouseEvent, node: FlowNode) { if (node.type === 'START') return; remember(); dragging.value = node.id; const sx = event.clientX; const sy = event.clientY; const x = node.x; const y = node.y; const move = (e: MouseEvent) => { node.x = Math.max(12, Math.round((x + e.clientX - sx) / 9) * 9); node.y = Math.max(20, Math.round((y + e.clientY - sy) / 9) * 9) }; const up = () => { dragging.value = null; window.removeEventListener('mousemove', move); window.removeEventListener('mouseup', up) }; window.addEventListener('mousemove', move); window.addEventListener('mouseup', up) }
function addNode(type: NodeType) { remember(); const base = selectedNode.value; const id = `${type.toLowerCase()}-${Date.now()}`; const node: FlowNode = { id, name: type === 'USER_TASK' ? '人工审批' : type === 'CONDITION' ? '条件分支' : type === 'SERVICE_TASK' ? '服务任务' : '结束', type, x: (base?.x ?? 300) + 180, y: (base?.y ?? 160) + (type === 'CONDITION' ? 0 : 20), assignee: type === 'USER_TASK' ? '待配置' : '' }; nodes.value.push(node); if (base && base.type !== 'END') { const old = edges.value.find(e => e.source === base.id); if (old) { old.source = id; edges.value.push({ id: `edge-${Date.now()}`, source: base.id, target: id, condition: '' }) } else edges.value.push({ id: `edge-${Date.now()}`, source: base.id, target: id, condition: '' }) } selectedId.value = id }
function deleteSelected() { if (selectedNode.value && selectedNode.value.type !== 'START') { remember(); const id = selectedNode.value.id; const incoming = edges.value.filter(e => e.target === id); const outgoing = edges.value.filter(e => e.source === id); nodes.value = nodes.value.filter(n => n.id !== id); edges.value = edges.value.filter(e => e.source !== id && e.target !== id); if (incoming.length === 1 && outgoing.length === 1) edges.value.push({ id: `edge-${Date.now()}`, source: incoming[0].source, target: outgoing[0].target, condition: outgoing[0].condition }); selectedId.value = '' } else if (selectedEdge.value) { remember(); edges.value = edges.value.filter(e => e.id !== selectedEdgeId.value); selectedEdgeId.value = '' } }
function graphPayload() { return { nodes: nodes.value.map(node => ({ id: node.id, name: node.name, type: node.type === 'CONDITION' ? 'EXCLUSIVE_GATEWAY' : node.type, properties: { assigneeRule: node.assignee && node.assignee !== '待配置' ? `role:${ASSIGNEE_ROLE_MAP[node.assignee] ?? node.assignee}` : undefined, x: String(node.x), y: String(node.y) } })), edges: edges.value.map(edge => ({ id: edge.id, source: edge.source, target: edge.target, condition: edge.condition })) } }
async function saveDraft() { try { const body = { key: 'expense-reimbursement', name: '费用报销审批', graph: graphPayload() }; const result = definitionId.value ? await api.updateDefinition(definitionId.value, { ...body, expectedRevision: definitionRevision.value }) : await api.definition(body); definitionId.value = result.id; definitionRevision.value = result.revision; notice.value = '流程草稿已保存，发布前仍需通过服务端校验' } catch (error) { notice.value = (error as ApiError).message ?? '保存失败，请检查流程定义服务' } }
async function publishDraft() { if (!definitionId.value) { notice.value = '请先保存流程草稿'; return }; try { await api.publishDefinition(definitionId.value, definitionRevision.value); notice.value = '流程已发布，新实例将使用当前版本' } catch (error) { notice.value = (error as ApiError).message ?? '发布失败，请先完成服务端校验' } }
function validate() { notice.value = nodes.value.some(n => n.type === 'USER_TASK' && (!n.assignee || n.assignee === '待配置')) ? '校验失败：存在未配置审批人的人工节点' : '校验通过：流程可以提交发布审核' }
function onDrop(event: DragEvent) { const type = event.dataTransfer?.getData('node-type') as NodeType; if (type) addNode(type) }
function edgePath(edge: FlowEdge) { const a = nodes.value.find(n => n.id === edge.source); const b = nodes.value.find(n => n.id === edge.target); if (!a || !b) return ''; const ax = a.x + 126; const ay = a.y + 32; const bx = b.x; const by = b.y + 32; const mx = (ax + bx) / 2; return `M ${ax} ${ay} L ${mx} ${ay} L ${mx} ${by} L ${bx} ${by}` }
function keyHandler(event: KeyboardEvent) { if (page.value !== 'designer') return; if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'z') { event.preventDefault(); event.shiftKey ? redo() : undo() }; if (event.key === 'Delete' || event.key === 'Backspace') { const target = event.target as HTMLElement; if (!['INPUT', 'TEXTAREA', 'SELECT'].includes(target.tagName)) deleteSelected() } }
</script>

<template>
  <div class="app" @keydown="keyHandler">
    <section v-if="!loggedIn" class="login-screen">
      <div class="login-orbit"><span></span><span></span><span></span></div>
      <div class="login-card"><div class="brand-mark">AF</div><p class="eyebrow">AGENTFLOW / WORKFLOW OS</p><h1>让每一次审批<br /><em>都有依据。</em></h1><p class="login-copy">面向 OA、财务与业务团队的智能审批工作台。</p><label>租户空间<input v-model="tenantId" placeholder="demo" /></label><label>用户名<input v-model="username" placeholder="admin" @keyup.enter="login" /></label><label>密码<input v-model="password" type="password" placeholder="请输入密码" @keyup.enter="login" /></label><button class="primary wide" @click="login">进入工作台 <span>↗</span></button><small>{{ notice || '演示环境：使用已配置的组织账号登录' }}</small></div>
    </section>
    <template v-else>
      <aside class="sidebar"><div class="brand"><div class="brand-mark">AF</div><div><strong>agentflow</strong><small>审批工作台</small></div></div><div class="space-label">WORKSPACE <span>⌄</span></div><nav><button :class="{active: page === 'workbench'}" @click="page = 'workbench'"><b>◉</b> 待我审批 <i>{{ tasks.length }}</i></button><button @click="page = 'workbench'"><b>↗</b> 我发起</button><button @click="page = 'workbench'"><b>◎</b> 抄送我的</button><button @click="page = 'workbench'"><b>✓</b> 已办记录</button><div class="nav-divider"></div><button :class="{active: page === 'designer'}" @click="page = 'designer'"><b>⌘</b> 流程管理</button><button @click="notice = 'Agent 助理即将接入当前申请上下文'"><b>✦</b> Agent 助理 <span class="new">NEW</span></button><div class="nav-divider"></div><p class="nav-caption">费用报销</p><button @click="page = 'expense'"><b>↳</b> 报销填报</button><button @click="page = 'expense'"><b>▣</b> 财务审核</button><button @click="page = 'expense'"><b>▤</b> 出纳付款台</button></nav><div class="sidebar-bottom"><div class="online-dot" :class="{offline: !serverAvailable}"></div><span>{{ serverAvailable ? '服务连接正常' : '服务连接异常' }}</span><button title="退出" @click="logout">↪</button></div></aside>
      <main class="main"><header><div class="crumb">当前空间 <strong>/</strong> {{ page === 'designer' ? '流程管理' : page === 'expense' ? '费用报销' : '审批工作台' }}</div><div class="header-actions"><button class="icon-button">⌕</button><button class="icon-button has-dot">♢</button><div class="avatar">{{ username.slice(0, 1).toUpperCase() || 'A' }}</div><span class="user-name">{{ username || 'Admin' }}</span></div></header>
        <div v-if="notice" class="toast" role="status">{{ notice }} <button @click="notice = ''">×</button></div>
        <section v-if="page === 'workbench'" class="content"><div class="page-heading"><div><p class="eyebrow">MONDAY, 26 MARCH 2026</p><h2>今天，先处理重要的事。</h2><p class="subhead">这里是你的审批责任链，共有 <strong>{{ tasks.length }}</strong> 项待处理。</p></div><button class="primary" @click="notice = '请选择申请类型开始填写'">＋ 发起申请</button></div><div class="metrics"><div><span class="metric-icon teal">◎</span><small>待我审批</small><strong>{{ tasks.length.toString().padStart(2, '0') }}</strong><em>服务端实时数据</em></div><div><span class="metric-icon blue">✓</span><small>本月已完成</small><strong>—</strong><em>等待服务端汇总</em></div><div><span class="metric-icon amber">!</span><small>预算预警</small><strong>—</strong><em>等待服务端汇总</em></div><div><span class="metric-icon purple">✦</span><small>Agent 预检</small><strong>—</strong><em>Agent 数据未接入</em></div></div><div class="work-grid"><div class="queue panel"><div class="panel-head"><div><h3>待办队列 <span class="count">{{ visibleTasks.length }}</span></h3><p>按优先级为你排列</p></div><button class="quiet">筛选⌄</button></div><div class="filters"><button v-for="filter in ['全部','高优先级','预算例外','临近 SLA']" :key="filter" :class="{selected: taskFilter === filter}" @click="taskFilter = filter">{{ filter }}</button></div><div v-if="!visibleTasks.length" class="queue-empty"><strong>当前没有待处理任务</strong><p>服务端没有返回可处理的审批任务。</p></div><button v-for="task in visibleTasks" :key="task.id" class="task-row" :class="{chosen: activeTask?.id === task.id}" @click="selectTask(task)"><span class="task-state" :class="task.risk === '预算例外' ? 'amber-bg' : task.risk === '高优先级' ? 'red-bg' : 'teal-bg'">{{ task.risk === '预算例外' ? '!' : task.risk === '高优先级' ? '↑' : '◷' }}</span><span class="task-main"><strong>{{ task.title }}</strong><small>{{ task.id }} · {{ task.applicant }}</small></span><span class="task-side"><strong>{{ task.amount }}</strong><small>{{ task.updated }}</small></span></button></div><div class="detail panel"><div v-if="activeTask" class="detail-body"><div class="detail-top"><div><span class="status-chip">● {{ activeTask.status }}</span><h3>{{ activeTask.title }}</h3><p>{{ activeTask.id }} · {{ activeTask.applicant }} 发起于今天 09:42</p></div><button class="more">···</button></div><div class="tabs"><button v-for="tab in [{key:'detail',label:'申请详情'},{key:'timeline',label:'时间线'},{key:'audit',label:'审计记录'}]" :key="tab.key" :class="{active: taskTab === tab.key}" @click="taskTab = tab.key as 'detail' | 'timeline' | 'audit'">{{ tab.label }}</button></div><div v-if="taskTab === 'detail'" class="detail-content"><div class="amount-box"><small>申请金额</small><strong>{{ activeTask.amount }}</strong><span>预计应付 ¥240.50 · 借款冲销 ¥3,000</span></div><div class="facts"><div><small>申请人</small><strong>{{ activeTask.applicant }} <i>产品部</i></strong></div><div><small>费用类型</small><strong>差旅费用报销</strong></div><div><small>成本中心</small><strong>CC-102 · 产品中心</strong></div><div><small>付款方式</small><strong>对公转账</strong></div></div><div class="agent-note"><span>✦</span><div><strong>Agent 证据</strong><p>当前申请尚未返回 Agent 预检证据。</p><small>服务端接入后显示来源、置信度和建议。</small></div></div><div class="timeline-mini"><div class="done"><b>✓</b><span><strong>申请已提交</strong><small>林晓 · 今天 09:42</small></span></div><div class="done"><b>✓</b><span><strong>部门负责人已批准</strong><small>王强 · 今天 10:06</small></span></div><div class="current"><b>●</b><span><strong>等待你的审批</strong><small>财务复核 · 现在</small></span></div></div></div><div v-else-if="taskTab === 'timeline'" class="timeline-full"><div v-for="item in ['申请已提交 · 林晓 · 今天 09:42','部门负责人已批准 · 王强 · 今天 10:06','Agent 预检完成 · 规则 EXP-07 · 今天 10:07','进入财务复核 · 等待当前处理人']" :key="item" class="event"><b>●</b><span>{{ item }}</span></div></div><div v-else class="audit-list"><p>动作记录按租户与任务权限加载</p><code>agent-run: precheck-7f19 · source: expense-policy</code><code>task-version: 4 · immutable event log</code></div><div class="action-bar"><button class="secondary" @click="action('转交')">转交</button><button class="return" @click="action('退回')">退回</button><button class="primary" @click="action('批准')">批准申请 <span>↗</span></button></div></div><div v-else class="empty-detail"><div class="empty-icon">◎</div><h3>选择一项待办</h3><p>从左侧队列选择申请，查看详情和 Agent 证据。</p></div></div></div></section>
        <section v-else-if="page === 'designer'" class="designer-page"><div class="designer-heading"><div><p class="eyebrow">PROCESS DEFINITION / DRAFT V2</p><h2>费用报销审批 <span class="draft-dot"></span></h2><p class="subhead">有未保存的修改 · 修改只作用于草稿，运行中实例保持原版本。</p></div><div class="designer-actions"><button class="secondary" @click="undo" :disabled="!history.length">↶</button><button class="secondary" @click="redo" :disabled="!future.length">↷</button><button class="secondary" @click="validate">校验流程</button><button class="secondary" @click="saveDraft">保存草稿</button><button class="primary" @click="publishDraft">发布 v2 ↗</button></div></div><div class="designer-layout"><aside class="palette"><h4>节点</h4><p>拖入画布，或点击添加</p><button v-for="item in palette" :key="item.type" draggable="true" @dragstart="(e) => e.dataTransfer?.setData('node-type', item.type)" @click="addNode(item.type)"><span>{{ item.icon }}</span>{{ item.label }}<b>＋</b></button><div class="palette-tip"><strong>设计器提示</strong><p>非分支节点只有一条出线。选中节点后可用方向键微调位置。</p></div></aside><div class="canvas-wrap"><div class="canvas-toolbar"><span>费用报销 / 默认审批流</span><div><button @click="notice = '已适应画布'">⊙ 适应画布</button><button @click="notice = '自动布局已生成，可撤销'">⌗ 自动布局</button><span class="zoom">−　100%　＋</span></div></div><div class="canvas" tabindex="0" @dragover.prevent @drop="onDrop"><svg class="edges" viewBox="0 0 1140 520" preserveAspectRatio="none"><path v-for="edge in edges" :key="edge.id" :d="edgePath(edge)" :class="{selected: selectedEdgeId === edge.id}" @click.stop="selectEdge(edge)" /><text v-for="edge in edges.filter(e => e.condition)" :key="`${edge.id}-label`" :x="((nodes.find(n => n.id === edge.source)?.x ?? 0) + (nodes.find(n => n.id === edge.target)?.x ?? 0)) / 2 + 42" :y="(nodes.find(n => n.id === edge.source)?.y ?? 0) + 23" class="edge-label">{{ edge.condition }}</text></svg><button v-for="node in nodes" :key="node.id" class="flow-node" :class="[node.type.toLowerCase(), {selected: selectedId === node.id, dragging: dragging === node.id}]" :style="{left: `${node.x}px`, top: `${node.y}px`}" @mousedown="(e) => moveNode(e, node)" @click.stop="selectNode(node)"><span class="node-icon">{{ node.type === 'CONDITION' ? '◇' : node.type === 'START' ? '▶' : node.type === 'END' ? '●' : node.type === 'SERVICE_TASK' ? '⚙' : '人' }}</span><strong>{{ node.name }}</strong><small v-if="node.assignee">{{ node.assignee }}</small><i class="port"></i></button></div></div><aside class="inspector"><div v-if="selectedNode"><div class="inspector-head"><div><p class="eyebrow">NODE PROPERTY</p><h3>{{ selectedNode.name }}</h3></div><button class="danger-icon" :disabled="selectedNode.type === 'START'" @click="deleteSelected">⌫</button></div><label>节点名称<input v-model="selectedNode.name" /></label><label>节点类型<select v-model="selectedNode.type"><option v-for="type in ['START','USER_TASK','CONDITION','END']" :key="type" :value="type">{{ type }}</option></select></label><label v-if="selectedNode.type === 'USER_TASK'">审批人策略<select v-model="selectedNode.assignee"><option>申请人直属上级</option><option>部门负责人</option><option>财务负责人</option><option>待配置</option></select></label><div v-if="selectedNode.type === 'CONDITION'" class="branch-editor"><div class="label-row"><strong>分支条件</strong><button @click="notice = '条件编辑器支持字段、运算符和取值组合'">＋ 添加</button></div><div v-for="edge in edges.filter(e => e.source === selectedNode?.id)" :key="edge.id" class="branch"><input v-model="edge.condition" placeholder="如：总额 ≤ 5000" /><button :class="{default: edge.defaultBranch}" @click="edge.defaultBranch = !edge.defaultBranch">{{ edge.defaultBranch ? '默认' : '设为默认' }}</button></div></div><label>连线到<select><option>选择下一节点</option><option v-for="node in nodes.filter(n => n.id !== selectedNode?.id)" :key="node.id">{{ node.name }}</option></select></label><button class="delete-button" :disabled="selectedNode.type === 'START'" @click="deleteSelected">删除节点</button></div><div v-else-if="selectedEdge" class="inspector-head"><div><p class="eyebrow">EDGE PROPERTY</p><h3>连线条件</h3><input v-model="selectedEdge.condition" placeholder="填写分支条件" /></div><button class="danger-icon" @click="deleteSelected">⌫</button></div><div v-else class="inspector-empty"><span>＋</span><h3>选择一个节点</h3><p>画布中的节点和连线都可以编辑。选中后在这里配置属性。</p></div></aside></div><div class="validation-strip"><span>●</span> 当前草稿已通过基础结构检查 <button @click="validate">查看校验结果 →</button></div></section>
        <section v-else class="content expense-page"><div class="page-heading"><div><p class="eyebrow">EXPENSE CONTROL / 2026</p><h2>费用报销</h2><p class="subhead">从填报、财务核减到付款，追踪每一笔费用的责任链。</p></div><button class="primary" @click="notice = '请选择报销类型开始填写'">＋ 新建报销单</button></div><div class="expense-cards"><article><span class="card-kicker">我的草稿</span><strong>02</strong><p>继续填写未完成的报销单</p><button @click="notice = '正在打开最近草稿'">查看草稿 →</button></article><article><span class="card-kicker">财务待审核</span><strong>08</strong><p>有 2 笔预算例外需要判断</p><button @click="notice = '已切换到财务审核队列'">进入审核台 →</button></article><article><span class="card-kicker">待付款</span><strong>04</strong><p>本批次预计付款 ¥18,420.00</p><button @click="notice = '已打开出纳付款台'">打开付款台 →</button></article></div><div class="expense-panel panel"><div class="panel-head"><div><h3>最近报销单</h3><p>每张单据保留原始发票、核减和付款审计记录</p></div><button class="quiet">导出记录 ↓</button></div><div class="expense-row" v-for="row in [{no:'EXP-2026-0326',name:'差旅费用报销',amount:'¥3,240.50',state:'财务审核'},{no:'EXP-2026-0318',name:'客户招待费用',amount:'¥1,280.00',state:'已付款'},{no:'EXP-2026-0312',name:'办公用品采购',amount:'¥860.00',state:'草稿'}]" :key="row.no"><span class="receipt-icon">▤</span><div><strong>{{ row.name }}</strong><small>{{ row.no }} · 更新于今天</small></div><b>{{ row.amount }}</b><span class="status-chip">{{ row.state }}</span><button class="more">···</button></div></div></section>
      </main>
    </template>
  </div>
</template>
